function __vunoraNorm(s: unknown) {
  return String(s).replace(/\s+/g, ' ').trim()
}

function __vunoraFieldsGlobal() {
  return (typeof window !== 'undefined' && window.__vunoraFields) || null
}

// Shared-block preview registry: a SEPARATE global from __vunoraFields so a
// shared block (collection 'shared-blocks') never clobbers a page doc that
// happens to share the same numeric id.
function __vunoraSharedFieldsGlobal() {
  return (typeof window !== 'undefined' && window.__vunoraSharedFields) || null
}

// Returns the docs map for a collection's preview registry ('pages' ->
// __vunoraFields, 'shared-blocks' -> __vunoraSharedFields). Anything else maps
// to the pages registry — only these two collections are ever tagged/edited.
function __vunoraRegistryDocs(collection: string) {
  var reg = collection === 'shared-blocks' ? __vunoraSharedFieldsGlobal() : __vunoraFieldsGlobal()
  return reg && reg.docs ? reg.docs : null
}

function __vunoraRegHasDocs(reg: any) {
  if (!reg || !reg.docs) return false
  for (var k in reg.docs) {
    if (Object.prototype.hasOwnProperty.call(reg.docs, k)) return true
  }
  return false
}

