  // Keep previously registered anchors: the fetched pages doc never carries
  // them (session provenance is delivered separately from source-field-spans).
  var prevAnchors = prev && prev.anchors ? prev.anchors : undefined
  reg.docs[id] = prevAnchors
    ? { id: id, slug: slug, fields: incoming, anchors: prevAnchors }
    : { id: id, slug: slug, fields: incoming }
  try { window.dispatchEvent(new CustomEvent('vunora:fields-ready')) } catch (e) { /* noop */ }
