// Parse rule for data-vunora-field: split on the FIRST two ':' only —
// fieldName may itself contain ':' or '.'.
function __vunoraParseFieldTag(raw: unknown) {
  var s = String(raw || '')
  var first = s.indexOf(':')
  if (first <= 0) return null
  var second = s.indexOf(':', first + 1)
  if (second < 0 || second === first + 1 || second === s.length - 1) return null
  return { collection: s.slice(0, first), docId: s.slice(first + 1, second), fieldName: s.slice(second + 1) }
}

function __vunoraStoredFieldValue(collection: string, docId: string, fieldName: string) {
  var docs = __vunoraRegistryDocs(collection)
  var doc = docs ? docs[String(docId)] : null
  var v = doc && doc.fields ? doc.fields[fieldName] : undefined
  return typeof v === 'string' ? v : null
}

function __vunoraStoreFieldValue(collection: string, docId: string, fieldName: string, value: string) {
  var docs = __vunoraRegistryDocs(collection)
  var doc = docs ? docs[String(docId)] : null
  if (doc && doc.fields) doc.fields[fieldName] = value
}

var __vunoraPreviewProvenance: any = {}

function __vunoraProvenanceKey(collection: string, docId: string, fieldName: string) {
  var id = String(docId)
  return collection + ':' + String(id.length) + ':' + id + String(fieldName)
}

// ── B-R2 build-time anchors ──
