  var doc = reg && reg.docs ? reg.docs[String(docId)] : null
  var fromDoc = doc && doc.anchors ? doc.anchors[fieldName] : undefined
  if (typeof fromDoc === 'string' && fromDoc) return fromDoc
  var cfg = __vunoraOverlayCfg()
  var ca = cfg && cfg.anchors
  if (ca && ca.fields && String(ca.docId) === String(docId)) {
    var fromCfg = ca.fields[fieldName]
    if (typeof fromCfg === 'string' && fromCfg) return fromCfg
  }
