function __vunoraMappingVersionForField(collection: string, docId: string, fieldName: string) {
  var authenticated = __vunoraPreviewProvenance[__vunoraProvenanceKey(collection, docId, fieldName)]
  return authenticated && typeof authenticated.mappingVersion === 'string'
    ? authenticated.mappingVersion
    : null
}

function __vunoraCmsValueRevisionForField(collection: string, docId: string, fieldName: string) {
  var authenticated = __vunoraPreviewProvenance[__vunoraProvenanceKey(collection, docId, fieldName)]
  return authenticated && typeof authenticated.cmsValueRevision === 'string'
    ? authenticated.cmsValueRevision
    : null
}

