  var hash = s.indexOf('#')
  if (hash < 0) return null
  var path = s.slice(hash + 1)
  if (!path) return null
  var at = path.lastIndexOf('@')
  if (at >= 0) {
    path = path.slice(0, at)
  } else {
    var slash = path.lastIndexOf('/')
    if (slash >= 0 && /^(?:text|expr)\[\d+\]$/.test(path.slice(slash + 1))) path = path.slice(0, slash)
  }
