      type: 'vunora-field-focus',
      previewSessionId: previewSessionId,
      messageId: focusMessageId,
      collection: 'pages',
      docId: info.docId,
      fieldName: info.fieldName,
      anchor: anchor,
      mappingVersion: mappingVersion,
